package com.uaefinancial.tracker.core

import org.junit.Test
import java.time.LocalDate
import kotlin.test.assertEquals

/**
 * A second, held-out set of layouts, written after the reader was improved on StatementReaderUnseenTest and run before any further change: made-up statements in the styles other UAE banks
 * use (key:value blocks, summary boxes, CR / (brackets) / minus / Dr-Cr columns for credits, ISO, "Sep 12, 2026"
 * and no-year dates, dotted leaders, account statements with running balances). Generated by a script so every
 * statement adds up: previous balance + spends - credits = balance.
 */
class StatementReaderHeldOutTest {
    private data class Expect(
        val sd: String? = null, val dd: String? = null, val total: Long? = null, val min: Long? = null, val limit: Long? = null,
        val avail: Long? = null, val prev: Long? = null, val n: Int, val deb: Long, val cred: Long, val last4: String?,
        val agree: Boolean, val account: Boolean = false,
    )

    private fun check(name: String, text: String, e: Expect): List<String> {
        val a = StatementReader.analyze(StatementReader.linesFromText(text), 2026)
        val s = a.summary
        val bad = mutableListOf<String>()
        fun cmp(field: String, want: Any?, got: Any?) { if (want != null && want != got) bad += "$name.$field: want $want got $got" }
        cmp("statementDate", e.sd?.let(LocalDate::parse), s.statementDate)
        cmp("dueDate", e.dd?.let(LocalDate::parse), s.dueDate)
        cmp("totalDue", e.total, s.totalDueMinor)
        cmp("minimumDue", e.min, s.minimumDueMinor)
        cmp("creditLimit", e.limit, s.creditLimitMinor)
        cmp("available", e.avail, s.availableLimitMinor)
        cmp("previous", e.prev, s.previousBalanceMinor)
        cmp("last4", e.last4, s.cardLast4)
        cmp("isAccount", e.account, s.isAccount)
        cmp("lines", e.n, a.lines.size)
        cmp("spends", e.deb, a.lines.filterNot { it.isCredit }.sumOf { it.amountMinor })
        cmp("credits", e.cred, a.lines.filter { it.isCredit }.sumOf { it.amountMinor })
        cmp("addsUp", e.agree, a.totalsAgree)
        return bad
    }

