    @Test fun held_out_layouts_are_read_correctly() {
        val problems = all.flatMap { (name, c) -> check(name, c.first, c.second) }
        println("HELD-OUT LAYOUTS: ${all.size - problems.map { it.substringBefore('.') }.distinct().size}/${all.size} fully right, ${problems.size} wrong fields")
        problems.forEach { println("  $it") }
        assertEquals(emptyList(), problems)
    }
